{
  "sql": "SELECT i.snapshot_date AS snapshot_date, p.category AS category, SUM(i.stock_on_hand) AS stock_on_hand FROM commerce.inventory AS i JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date = $1 GROUP BY i.snapshot_date, p.category ORDER BY 2 LIMIT 200",
  "parameters": [
    "2022-12-31"
  ],
  "explanation": "Aggregates stock on hand by category for the specific snapshot date 2022-12-31 as resolved in the validated interpretation."
}

